// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not the zero address to avoid edge cases
        vm.assume(caller != address(0));

        // Get current owner
        address currentOwner = c.owner();

        // Try calling owned() from caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // Rule: The call succeeds only if caller is the current owner,
        // and after the call the owner remains unchanged.
        assertTrue(
            (success && caller == currentOwner && c.owner() == currentOwner) ||
            (!success && caller != currentOwner && c.owner() == currentOwner)
        );
    }
}

